classdesc:
The ColorMatrix Filter Controller.

This filter controller manages the color matrix effect for a Camera.

The color matrix effect is a visual technique that involves manipulating the colors of an image
or scene using a mathematical matrix. This process can adjust hue, saturation, brightness, and contrast,
allowing developers to create various stylistic appearances or mood settings within the game.
Common applications include simulating different lighting conditions, applying color filters,
or achieving a specific visual style.

A ColorMatrix effect is added to a Camera via the FilterList component:

```js
const camera = this.cameras.main;

const cmFilter = camera.filters.internal.addColorMatrix();
camera.filters.external.addColorMatrix();

// To set the matrix values:
cmFilter.colorMatrix.sepia();
```

examples:
// Use just the transfer image, with unified alpha,
// where the base alpha is derived from inverted base brightness.
myFilter.setupAlphaTransfer(false, true, false, false, true);

const camera = this.cameras.main;
camera.filters.internal.addGradientMap(); // Basic effect.
camera.filters.external.addGradientMap({
    colorFactor: [ -0.3, -0.6, -0.1, 0 ],
    color: [ 0.3, 0.6, 0.1, 0 ]
}); // Invert brightness.

// Cache a panorama image in a scene.
// Assume there is a panorama texture called 'panorama'.
var panorama = this.add.image(0, 0, 'panorama');
panorama.setPosition(panorama.width / 2, panorama.height / 2);
panorama.enableFilters().filters.internal.addPanoramaBlur({});

var panoramaBlurred = this.textures.addDynamicTexture('panorama-blurred', panorama.width, panorama.height);
panoramaBlurred.draw(panorama).render();

panorama.destroy();

// Use the blurred panorama in a filter.
anotherObject.enableFilters().filters.internal.addImageLight({ environmentMap: 'panorama-blurred' });

// Create a customizable Bloom effect.
const camera = this.cameras.main;
const parallelFilters = camera.filters.internal.addParallelFilters();
parallelFilters.top.addThreshold(0.5, 1);
parallelFilters.top.addBlur();
parallelFilters.blend.blendMode = Phaser.BlendModes.ADD;
parallelFilters.blend.amount = 0.5;

// Create a customizable Bloom effect.
const camera = this.cameras.main;
const parallelFilters = camera.filters.internal.addParallelFilters();
parallelFilters.top.addThreshold(0.5, 1);
parallelFilters.top.addBlur();
parallelFilters.blend.blendMode = Phaser.BlendModes.ADD;
parallelFilters.blend.amount = 0.5;

const camera = this.cameras.main;
camera.filters.internal.addQuantize(); // Default effect.
camera.filters.external.addQuantize({
    steps: [ 16, 1, 1, 1 ],
    dither: true,
    mode: 1
}); // Quantize into 16 fully saturated rainbow hues, and dither.

